CREATE TABLE IF NOT EXISTS garantias(id BIGSERIAL PRIMARY KEY, ordem_id VARCHAR(80) UNIQUE NOT NULL, evento_id VARCHAR(80) UNIQUE NOT NULL, cliente_nome VARCHAR(160), inicio TIMESTAMPTZ, termino TIMESTAMPTZ, prazo_dias INTEGER);
CREATE TABLE IF NOT EXISTS avisos_atendimento(id BIGSERIAL PRIMARY KEY, evento_id VARCHAR(80) UNIQUE NOT NULL, ordem_id VARCHAR(80), cliente_nome VARCHAR(160), tipo VARCHAR(80), mensagem TEXT, criado_em TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS lancamentos_caixa(id BIGSERIAL PRIMARY KEY, evento_id VARCHAR(80) UNIQUE NOT NULL, ordem_id VARCHAR(80), tipo VARCHAR(80), valor NUMERIC(12,2), ocorrido_em TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS auditoria_eventos(id BIGSERIAL PRIMARY KEY, evento_id VARCHAR(80) UNIQUE NOT NULL, tipo VARCHAR(100), ordem_id VARCHAR(80), payload TEXT, ocorrido_em TIMESTAMPTZ, recebido_em TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS tarefas_pos_venda(id BIGSERIAL PRIMARY KEY, evento_id VARCHAR(80) UNIQUE NOT NULL, ordem_id VARCHAR(80), cliente_nome VARCHAR(160), data_contato DATE, instancia VARCHAR(100), criado_em TIMESTAMPTZ DEFAULT NOW());
